"""Generate local preview pages using the existing site's visual system."""
from html import escape
from pathlib import Path

ROOT = Path(__file__).parent

def link(path, text):
    return f'<a class="text-link" href="{path}">{text} <span aria-hidden="true">↗</span></a>'

def page(path, title, description, body):
    folder = ROOT / path
    folder.mkdir(parents=True, exist_ok=True)
    prefix = '../' * len(Path(path).parts)
    nav = [('dvyhuny/', 'Двигуни'), ('posluhy/', 'Послуги'), ('mahazyn/', 'Магазин'), ('kontakty/', 'Контакти')]
    nav_html = ''.join(f'<a href="{prefix}{p}">{t}</a>' for p, t in nav)
    doc = f'''<!doctype html><html lang="uk"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex, nofollow"><meta name="description" content="{escape(description, quote=True)}"><title>{escape(title)} | TIR Service</title><link rel="stylesheet" href="{prefix}styles.css"><link rel="stylesheet" href="{prefix}preview.css"><script src="{prefix}app.js" defer></script></head>
<body><a class="skip" href="#main">Перейти до вмісту</a><header class="header"><a class="brand" href="{prefix}" aria-label="TIR Service, на головну"><span class="brand-mark">TIR</span><span>SERVICE<br>РЕМОНТ ДВИГУНІВ</span></a><nav aria-label="Основна навігація">{nav_html}</nav><a class="header-link" href="{prefix}kontakty/">Обговорити ремонт ↗</a></header><main id="main">{body}</main><footer><a class="brand" href="{prefix}"><span class="brand-mark">TIR</span><span>SERVICE<br>РЕМОНТ ДВИГУНІВ</span></a><p>Ремонт двигунів вантажної та спеціальної техніки</p><a href="{prefix}pro-kompaniiu/">Про компанію</a><a href="{prefix}yak-my-pratsiuiemo/">Як ми працюємо</a><a href="{prefix}pytannia/">Питання</a><a href="{prefix}dostavka/">Доставка та оплата</a><span>УКРАЇНА</span></footer></body></html>'''
    (folder / 'index.html').write_text(doc, encoding='utf-8')

def hero(crumb, heading, intro, prefix='../'):
    return f'<section class="inner-hero"><div class="inner-wrap"><p class="breadcrumbs"><a href="{prefix}">Головна</a> / {crumb}</p><h1>{heading}</h1><p class="inner-intro">{intro}</p>{link(prefix + "kontakty/", "Підготувати звернення")}</div></section>'

page('posluhy', 'Послуги', 'Ремонт двигунів і підбір ущільнень для вантажної та спеціальної техніки.',
 hero('Послуги', 'Рішення для двигуна та його деталей.', 'Розкажіть про двигун, його стан або потрібну деталь. Можливість і склад робіт уточнюються індивідуально.') + '''<section class="section"><div class="service-list"><article><span class="service-index">01</span><div><h3>Ремонт дизельних двигунів</h3><p>Від розбирання й вимірювань до складання та випробувань, коли вони передбачені для конкретного двигуна.</p>''' + link('remont-dyzelnykh-dvyhuniv/', 'Детальніше про ремонт') + '''</div></article><article><span class="service-index">02</span><div><h3>Підбір ущільнень</h3><p>Прокладки, гумові кільця та ремкомплекти за запитом.</p>''' + link('../ushchilnennia/', 'Детальніше про деталі') + '</div></article></div></section>')

page('posluhy/remont-dyzelnykh-dvyhuniv', 'Ремонт дизельних двигунів', 'Ремонт дизельних двигунів: оцінка стану, відновлення, складання та випробування за умовами замовлення.',
 hero('Послуги / Ремонт двигунів', 'Ремонт починається з розуміння стану двигуна.', 'Обсяг робіт визначають за моделлю, модифікацією та результатами дефектації.', '../../') + '''<section class="section inner-content"><div><h2>Що може входити до ремонту</h2><p>Залежно від завдання роботи можуть включати розбирання, очищення та миття, вимірювання деталей, відновлення придатних або заміну непридатних компонентів і подальше складання.</p><p>Для окремих двигунів передбачаються стендові випробування. Частину випробувань проводять профільні підрядники. Можливість відеофіксації та оформлення протоколу уточнюється для конкретного замовлення.</p></div><div><h2>Умови обговорюються окремо</h2><p>Вартість залежить від типу двигуна, його стану та потрібних запчастин. Строки й склад ремонту визначають після дефектації. Умови діагностики та гарантії узгоджуються за конкретним замовленням.</p><p>У практиці підприємства трапляються питання до паливної апаратури та зношення гільз, кілець і вкладишів. Причину несправності встановлюють після оцінювання двигуна.</p></div></section><figure class="repair-image"><img src="../../engine-inspection-illustration.png" alt="Ілюстрація вимірювання деталі дизельного двигуна" loading="lazy" width="1774" height="887"><figcaption>Ілюстративне зображення, створене за допомогою ШІ</figcaption></figure><section class="section soft-section"><h2>Підготуйте інформацію для розмови.</h2><p class="measure">Повне маркування, назва техніки, опис несправності, доступні фото й історія попередніх ремонтів допоможуть розпочати обговорення.</p>''' + link('../../kontakty/', 'Підготувати запит') + '</section>')

models = ['1Д20','3Д20','1Д6','У1Д6','У1Д12','5Д20','5Д20Б-300','5Д20К-300','УТД-20','В-6','В-46','В-55','В-59','В-84','В-92','ЯМЗ-238','КамАЗ','Урал','КрАЗ','Cummins ISLE-350','Cummins VTA-903T','Detroit Diesel']
