page('dvyhuny', 'Двигуни', 'Перелік двигунів і позначень для запиту щодо ремонту.',
 hero('Двигуни', 'Знайдіть свій двигун.', 'Введіть маркування у пошук. Для уточнення можливості ремонту важливе повне позначення та модифікація.') + f'''<section class="section"><div class="search-wrap"><label for="engine-search">Пошук за моделлю двигуна</label><input id="engine-search" type="search" placeholder="Наприклад, 3Д20 або Cummins" autocomplete="off"><span aria-hidden="true">⌕</span></div><div class="engine-grid" id="engine-list" aria-live="polite">{items}</div><p id="no-results" hidden>Модель не знайдена. Уточніть можливість ремонту окремо.</p><p class="section-note">КамАЗ, Урал і КрАЗ вказані як назви техніки, Detroit Diesel — як виробник. Для них потрібна конкретна модель двигуна або серія.</p></section>''')

page('dvyhuny/1d20', 'Двигун 1Д20', 'Інформація для звернення щодо двигуна 1Д20 та його ущільнень.',
 hero('Двигуни / 1Д20', 'Двигун 1Д20: уточнити ремонт.', 'Для обговорення ремонту або підбору деталі важливі повне маркування та комплектація конкретного агрегату.', '../../') + '''<section class="section inner-content"><div><h2>Що підготувати</h2><p>Повідомте повний індекс двигуна, назву техніки або установки, опишіть несправність чи потрібну деталь. За можливості підготуйте фото таблички та вузла, дані про напрацювання й попередні ремонти.</p></div><div><h2>Уточнення щодо ремонту</h2><p>Конструкція та режими роботи двигунів 1Д20, 3Д20 і 5Д20 відрізняються. Можливість робіт, випробувань і підбору ущільнень для конкретного виконання потрібно узгодити окремо.</p><p>Опис загального процесу ремонту наведений на сторінці послуги. Він не означає, що кожна операція доступна для будь-якої модифікації.</p>''' + link('../../posluhy/remont-dyzelnykh-dvyhuniv/', 'Як обговорюється ремонт') + '</div></section>')

page('ushchilnennia', 'Кільця, прокладки та ремкомплекти', 'Підбір ущільнень і ремкомплектів для двигунів за запитом.',
 hero('Ущільнення', 'Коли важлива кожна деталь.', 'Прокладки, гумові кільця та ремкомплекти підбирають за точним двигуном і вузлом застосування.') + '''<section class="section inner-content"><div><h2>Підбір за запитом</h2><p>Для пошуку потрібного ущільнення підготуйте маркування двигуна, його модифікацію, назву вузла та кількість. Якщо є артикул, креслення чи фото деталі, вони допоможуть уточнити запит.</p><p>Частину прокладок підприємство виготовляє самостійно. Можливість виготовлення конкретної деталі, сумісність, наявність і ціну узгоджують окремо.</p></div><div><h2>Що можна уточнити</h2><ul class="clean-list"><li>Гумові ущільнювальні кільця</li><li>Прокладки до вузлів двигуна</li><li>Ремкомплекти за конкретним запитом</li></ul><p>Каталог конкретних товарів і сумісності перебуває в підготовці.</p></div></section><section class="section soft-section"><h2>Підготуйте запит на деталь.</h2><p class="measure">Вкажіть модель, модифікацію, вузол та кількість. Фото можна буде додати безпосередньо у месенджері після підключення контактів.</p>''' + link('../kontakty/?type=parts#request-form', 'Підготувати запит') + '</section>')

page('pro-kompaniiu', 'Про компанію', 'Ремонт двигунів та підбір ущільнень для клієнтів з усієї України.',
 hero('Про компанію', 'Робота з двигуном починається з деталей.', 'Ремонт двигунів вантажної та спеціальної техніки, а також підбір ущільнень за конкретним запитом.') + '''<section class="section inner-content"><div><h2>Як ми працюємо</h2><p>Роботи переважно виконують на території підприємства. Для деяких двигунів стендові випробування можуть проводити залучені профільні підрядники.</p><p>Запасні частини для ремонту отримують через постачальників. Потребу в деталях визначають за результатами оцінювання двигуна.</p></div><div><h2>Звернення з усієї України</h2><p>Працюємо із запитами приватних клієнтів, підприємств та ремонтних організацій з різних регіонів України. Можливість виїзду спеціалістів в окремих випадках обговорюється індивідуально.</p>''' + link('../kontakty/', 'Як підготувати звернення') + '</div></section>')

page('kontakty', 'Звернення та контакти', 'Підготуйте інформацію для звернення щодо ремонту двигуна або підбору деталі.',
 hero('Звернення', 'Розкажіть про ваше завдання.', 'Для звернень плануються телефон, WhatsApp та Viber. Контактні дані будуть додані після підтвердження.') + '''<section class="section request-layout"><div><h2>Що варто підготувати</h2><p>Оберіть тип запиту та заповніть поля. У цій локальній версії заявка нікуди не надсилається; підготовлений текст можна скопіювати.</p><p>Номер телефону, посилання на месенджери, адреса та графік ще не надані.</p></div><div><form id="request-form"><label for="request-type">Тип звернення</label><select id="request-type"><option value="Ремонт двигуна">Ремонт двигуна</option><option value="Підбір деталі">Підбір деталі</option></select><label for="request-engine">Модель або маркування двигуна</label><input id="request-engine" required maxlength="100" placeholder="Наприклад, 1Д20"><label for="request-description">Опис завдання або потрібного вузла</label><textarea id="request-description" required maxlength="1000" rows="5" placeholder="Опишіть несправність або деталь і кількість"></textarea><button class="button" type="submit">Підготувати текст <span aria-hidden="true">↗</span></button><p class="form-note">Демонстрація: дані залишаються у вашому браузері, заявку не буде надіслано.</p></form><div id="request-result" hidden><label for="request-text">Текст звернення</label><textarea id="request-text" rows="6" readonly></textarea><button class="outline-button" type="button" id="copy-request">Скопіювати текст</button><p id="copy-status" role="status"></p></div></div></section>''')

engine_drafts = [
 ('1d6', '1Д6', 'Повне позначення має значення', 'У дослідженні зустрічаються різні виконання 1Д6, зокрема 1Д6-150 та 1Д6-150С2-01. Суфікс допомагає визначити комплектацію; позначення У1Д6 потрібно розглядати окремо.', 'Дані для підбору', 'Передайте повний індекс із таблички, назву установки, опис несправності та історію попередніх робіт. Для ущільнення знадобляться вузол і, за можливості, номер або фото деталі.'),
 ('5d20', '5Д20', 'Модифікацію потрібно уточнити', '5Д20Б-300 та 5Д20К-300 наведені як різні виконання. Не варто припускати однакову комплектацію або взаємозамінність деталей без перевірки конкретного двигуна.', 'Підготовка до звернення', 'Знайдіть повне маркування й назву техніки. Для ремонту опишіть проблему, а для підбору прокладки чи кільця вкажіть вузол та наявні дані деталі.'),
 ('v-6', 'В-6', 'Уточнюйте виконання двигуна', 'Позначення В-6 використовують для конкретного двигуна; воно не тотожне загальному позначенню V6. У наданому дослідженні згадуються різні виконання, зокрема В-6В, В-6М та В-6П.', 'Як визначити потрібну деталь', 'Для звернення підготуйте фото маркування та наявної деталі, назву вузла й опис завдання. Сумісність ущільнень визначається за конкретним виконанням.'),
 ('v-46', 'В-46', 'Важливий повний індекс', 'У дослідженні зазначені різні виконання В-46, серед них В-46-1 та В-46-6. Їхні параметри та комплектація потребують перевірки за документацією конкретного агрегату.', 'Що передати для оцінювання', 'Назвіть модифікацію, техніку та опишіть ознаки несправності. Фото таблички й історія ремонту допоможуть обговорити можливість і обсяг робіт.'),
 ('yamz-238', 'ЯМЗ-238', 'Визначте модифікацію', 'ЯМЗ-238 має різні виконання. Для розмови про ремонт або підбір ущільнень потрібне повне маркування саме вашого двигуна.', 'Двигун і техніка', 'Назва КрАЗ сама по собі не визначає модель двигуна. Звірте індекс із табличкою або документами та повідомте його разом із назвою техніки.'),
]
